using AIPMS.Application.Abstractions.Security;using AIPMS.Application.Common.Exceptions;using AIPMS.Application.Common.Models;using AIPMS.Application.Features.Evaluations.Abstractions;using AIPMS.Application.Features.Evaluations.Commands;using AIPMS.Application.Features.Evaluations.DTOs;using MediatR;
namespace AIPMS.Application.Features.Evaluations.Queries;
public sealed record GetEvaluationQuery(long Id):IRequest<EvaluationDetailDto>;public sealed record GetProjectEvaluationsQuery(long ProjectId,int PageNumber=1,int PageSize=20):IRequest<PagedResult<EvaluationDto>>;
public sealed class GetEvaluationHandler(ICurrentUser u,IEvaluationRepository r):IRequestHandler<GetEvaluationQuery,EvaluationDetailDto>{public async Task<EvaluationDetailDto> Handle(GetEvaluationQuery x,CancellationToken ct){var e=await r.GetAsync(x.Id,ct)??throw new NotFoundException("Evaluation",x.Id);await EvaluationAccess.Ensure(EvaluationAccess.UserId(u),e,r,ct);return e;}}
public sealed class GetProjectEvaluationsHandler(ICurrentUser u,IEvaluationRepository r):IRequestHandler<GetProjectEvaluationsQuery,PagedResult<EvaluationDto>>{public async Task<PagedResult<EvaluationDto>> Handle(GetProjectEvaluationsQuery x,CancellationToken ct){if(!await r.CanEvaluateProjectAsync(EvaluationAccess.UserId(u),x.ProjectId,ct))throw new ForbiddenException();return await r.GetByProjectAsync(x.ProjectId,x.PageNumber,x.PageSize,ct);}}
